 public async Task LoadProject(SongProject p){
  Stop();ProjectRules.Validate(p);foreach(var declared in new[]{p.Dance,p.Camera,p.Audio})if(declared.Path.Length>0&&!File.Exists(declared.Path))throw new FileNotFoundException("프로젝트 원본 파일이 없습니다: "+declared.Path);SetBusy(true,"프로젝트 파일을 읽는 중…");
  try {
   // Keep the current project, assets and save destination intact until all reads succeed.
   if(!DanceStudio.Rig.IsBuiltin(p.Skeleton)&&!File.Exists(p.Skeleton)){p.Skeleton=DanceStudio.Rig.BuiltinId;status.Text="원본 스켈레톤 파일이 없어 내장 스켈레톤을 사용합니다. 본 매핑은 다시 검증합니다.";}var loadedRig=await Task.Run(()=>DanceStudio.Rig.Load(p.Skeleton));var loadedDance=File.Exists(p.Dance.Path)?await LoadMotion(p.Dance.Path,p.Dance.HkxBindingIndex,p.Dance.IdentityRigProof,loadedRig):null;var loadedCamera=File.Exists(p.Camera.Path)?await LoadMotion(p.Camera.Path,p.Camera.HkxBindingIndex,p.Camera.IdentityRigProof,loadedRig):null;var loadedAudio=File.Exists(p.Audio.Path)?await Task.Run(()=>AudioImport.Load(p.Audio.Path)):null;var loaded=(rig:loadedRig,dance:loadedDance,cam:loadedCamera,audio:loadedAudio);if(loadedDance!=null){p.Dance.HkxBindingIndex=loadedDance.BindingIndex;p.Dance.IdentityRigProof=loadedDance.IdentityRigProof;}if(loadedCamera!=null){p.Camera.HkxBindingIndex=loadedCamera.BindingIndex;p.Camera.IdentityRigProof=loadedCamera.IdentityRigProof;if(p.CameraBone>=loadedRig.Names.Length)throw new InvalidDataException("카메라 기준 본이 스켈레톤 범위를 벗어납니다.");}

   Project=p;Rig=loaded.rig;Dance=loaded.dance;CameraClip=loaded.cam;Audio=loaded.audio;projectPath=null;
   stage.SetRig(Rig);camera.SetRig(Rig);updating=true;try{bones.ItemsSource=Rig.Names.Select((name,i)=>new BoneItem(i,name)).ToList();}finally{updating=false;}
   if(p.CameraBone<0&&CameraClip!=null)AutoCamera();timeline.Span=Math.Max(10,Math.Max(p.ExportOut,Math.Max(p.Dance.TimelineEnd,Math.Max(p.Camera.TimelineEnd,p.Audio.TimelineEnd)))*1.03);timeline.ViewStart=0;
   Seek(p.ExportIn);RefreshFields();dirty=false;SetBusy(false,AllReady?"편집 준비 완료 · 시작 버튼 또는 Space로 미리보기":"일부 원본이 없습니다. 각 파일을 다시 선택하세요.");
  }catch{SetBusy(false,"프로젝트를 불러오지 못했습니다. 기존 작업을 유지합니다.");throw;}
